{
  "aggregate_id": "DEF-NRS-484B-018::electric_scooter",
  "classifications": [
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The contract omits the required weight and speed limits, while the incorporated vehicle definition's self-referential scooter exception conflicts with the affirmative description rather than providing an unambiguous class decision."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The incorporated vehicle definition expressly excepts electric bicycles, and the electric-bicycle definition expressly disclaims electric scooters."
    },
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The exception for devices moved by human power describes the human-powered devices specified by this contract."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract specifies on-track equipment but does not require exclusive use upon stationary rails, so the exception does not establish that every member is removed."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The jurisdictional moped definition expressly states that the term does not include an electric scooter."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "contradicted",
      "reason": "The contract describes a person rather than a vehicle, and a wheelchair potentially satisfying vehicle specifications does not make its occupant the device defined as an electric scooter."
    },
    {
      "class": "ru.child",
      "verdict": "contradicted",
      "reason": "A child pedestrian is a person rather than the vehicle required by the definition, regardless of the specifications of a wheelchair the child occupies."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "contradicted",
      "reason": "The contract describes a pedestrian person, whose possible use of a qualifying wheelchair does not identify that person with the vehicle required by the definition."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract neither guarantees the required scooter features and numerical limits nor rules them out for every permitted self-propelled vehicle."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Two or three wheels and an astride riding position neither establish nor preclude the required electric propulsion, weight and motor-only speed."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not determine the configuration, propulsion, weight or speed needed to settle membership under the posted definition."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official service and identifying livery or equipment neither establish nor preclude the definition's physical and performance requirements."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "The unspecified commercial-mass threshold and alternative commercial-licensing criterion do not determine whether every member satisfies or fails the scooter requirements."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "Being designed to carry many passengers does not contractually establish a weight above 100 pounds or incompatibility with the stated riding configuration."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School-bus designation and markings add no contractual weight or configuration restriction establishing that the admitting words reach no member."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public-transit service and identifying displays do not establish that every member exceeds the weight limit or fails the riding-position requirement."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "The tour, shuttle and lengthened-passenger-vehicle alternatives specify neither a minimum unladen weight nor a configuration necessarily incompatible with the quoted requirements."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "The passenger-for-hire contract and identifying markings do not require a weight above 100 pounds or exclude handlebars and an electric motor."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body does not itself establish excessive weight or incompatibility with a vehicle designed to be ridden upright or seated."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting function imposes no contractual minimum weight or prohibition on handlebars and electric propulsion."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The contract includes combinations as well as drawn vehicles, and the quoted propulsion and weight requirements do not establish that every combination fails them."
    }
  ]
}

